output:
resource "aws_s3_bucket" "data" {
  bucket = "acme-private-data"

  tags = {
    Name = "acme-private-data"
  }
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket = "acme-log-archive"
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "archive-old-logs"
    status = "Enabled"

    filter {
      prefix = "logs/"
    }

    transition {
      days          = 60
      storage_class = "STANDARD_IA"
    }

    transition {
      days          = 180
      storage_class = "GLACIER"
    }

    expiration {
      days = 365
    }
  }
}

resource "aws_s3_bucket" "secure" {
  bucket = "acme-must-use-tls"
}

resource "aws_s3_bucket_policy" "secure" {
  bucket = aws_s3_bucket.secure.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.secure.arn,
          "${aws_s3_bucket.secure.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_dynamodb_table" "carts" {
  name         = "shopping-carts"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "customer_id"

  attribute {
    name = "customer_id"
    type = "S"
  }

  tags = {
    Component = "cart"
  }
}

resource "aws_dynamodb_table" "users" {
  name         = "users"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "user_id"

  attribute {
    name = "user_id"
    type = "S"
  }

  attribute {
    name = "email"
    type = "S"
  }

  global_secondary_index {
    name            = "email-index"
    hash_key        = "email"
    projection_type = "ALL"
  }
}

resource "aws_ebs_volume" "data" {
  availability_zone = "us-east-1a"
  size              = 100
  type              = "gp3"
  encrypted         = true

  tags = {
    Name = "data-volume"
  }
}

resource "aws_volume_attachment" "data" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.data.id
  instance_id = aws_instance.app.id
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = "t3.small"
}

variable "ami_id" {
  type = string
}

resource "aws_db_subnet_group" "db" {
  name       = "acme-db-subnets"
  subnet_ids = var.private_subnet_ids

  tags = {
    Name = "acme-db-subnets"
  }
}

resource "aws_db_instance" "postgres" {
  identifier              = "acme-postgres"
  engine                  = "postgres"
  engine_version          = "16"
  instance_class          = "db.t4g.medium"
  allocated_storage       = 100
  db_name                 = "acme"
  username                = "acme_admin"
  manage_master_user_password = true
  db_subnet_group_name    = aws_db_subnet_group.db.name
  vpc_security_group_ids  = [var.db_sg_id]
  skip_final_snapshot     = false
  final_snapshot_identifier = "acme-postgres-final"
  backup_retention_period = 7

  tags = {
    Name = "acme-postgres"
  }
}

variable "private_subnet_ids" {
  type = list(string)
}

variable "db_sg_id" {
  type = string
}

resource "aws_efs_file_system" "shared" {
  creation_token = "acme-shared-fs"
  encrypted      = true

  tags = {
    Name = "acme-shared-fs"
  }
}

resource "aws_efs_mount_target" "shared" {
  count = 2

  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = [var.efs_sg_id]
}

variable "subnet_ids" {
  type = list(string)
}

variable "efs_sg_id" {
  type = string
}

resource "aws_ecr_repository" "app" {
  name                 = "acme/app"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Keep last 10 images"
        selection = {
          tagStatus     = "any"
          countType     = "imageCountMoreThan"
          countNumber   = 10
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

resource "aws_backup_vault" "db" {
  name = "db-backup-vault"
}

resource "aws_backup_plan" "db" {
  name = "db-weekly-backup"

  rule {
    rule_name         = "weekly"
    target_vault_name = aws_backup_vault.db.name
    schedule          = "cron(0 5 ? * SUN *)"

    lifecycle {
      cold_storage_after = 30
      delete_after       = 365
    }
  }
}

resource "aws_backup_selection" "db" {
  plan_id = aws_backup_plan.db.id
  name    = "db-instances"

  iam_role_arn = var.backup_role_arn
  resources    = [var.db_instance_arn]
}

variable "backup_role_arn" {
  type = string
}

variable "db_instance_arn" {
  type = string
}

resource "aws_s3_bucket" "source" {
  bucket = "acme-replication-source"
}

resource "aws_s3_bucket" "destination" {
  bucket = "acme-replication-destination"
}

resource "aws_s3_bucket_replication_configuration" "source" {
  role   = var.replication_role_arn
  bucket = aws_s3_bucket.source.id

  rule {
     id     = "replicate-all"
     status = "Enabled"

     destination {
       bucket        = aws_s3_bucket.destination.arn
       storage_class = "STANDARD"
     }

     filter {
       prefix = ""
     }
  }
}

resource "aws_s3_bucket_versioning" "source" {
  bucket = aws_s3_bucket.source.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "destination" {
  bucket = aws_s3_bucket.destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

variable "replication_role_arn" {
  type = string
}

resource "aws_dynamodb_table" "tokens" {
  name         = "api-tokens"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "token"

  attribute {
    name = "token"
    type = "S"
  }

  ttl {
    attribute_name = "expires_at"
    enabled        = true
  }
}

resource "aws_elasticache_subnet_group" "redis" {
  name       = "acme-redis-subnets"
  subnet_ids = var.private_subnet_ids
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "acme-redis"
  engine               = "redis"
  engine_version       = "7.1"
  node_type            = "cache.t4g.small"
  num_cache_nodes      = 1
  parameter_group_name = "redis7"
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.redis.name
  security_group_ids   = [var.redis_sg_id]
}

variable "private_subnet_ids" {
  type = list(string)
}

variable "redis_sg_id" {
  type = string
}

resource "aws_s3_bucket" "internal" {
  bucket = "acme-internal-artifacts"
}

resource "aws_s3_bucket_public_access_block" "internal" {
  bucket = aws_s3_bucket.internal.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "internal" {
  bucket = aws_s3_bucket.internal.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "acme-aurora"
  engine                  = "aurora-postgresql"
  engine_version          = "16.4"
  database_name           = "acme"
  master_username         = "acme_admin"
  manage_master_user_password = true
  backup_retention_period = 14
  preferred_backup_window = "03:00-04:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora.name
  vpc_security_group_ids  = [var.db_sg_id]
  storage_encrypted       = true
}

resource "aws_rds_cluster_instance" "aurora" {
  identifier         = "acme-aurora-writer"
  cluster_identifier = aws_rds_cluster.aurora.id
  instance_class     = "db.r6g.large"
  engine             = aws_rds_cluster.aurora.engine
  engine_version     = aws_rds_cluster.aurora.engine_version
}

resource "aws_db_subnet_group" "aurora" {
  name       = "aurora-subnets"
  subnet_ids = var.private_subnet_ids
}

variable "private_subnet_ids" {
  type = list(string)
}

variable "db_sg_id" {
  type = string
}

resource "aws_s3_bucket" "config" {
  bucket = "acme-app-config"
}

resource "aws_s3_object" "app_config" {
  bucket       = aws_s3_bucket.config.id
  key          = "config/app.json"
  source       = "${path.module}/app.json"
  etag         = filemd5("${path.module}/app.json")
  content_type = "application/json"
}

resource "aws_s3_bucket" "website" {
  bucket = "acme-docs-website"
}

resource "aws_s3_bucket_website_configuration" "website" {
  bucket = aws_s3_bucket.website.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "404.html"
  }
}

resource "aws_appautoscaling_target" "reads" {
  max_capacity       = 20
  min_capacity       = 5
  resource_id        = "table/${aws_dynamodb_table.hot.name}"
  scalable_dimension = "dynamodb:table:ReadCapacityUnits"
  service_namespace  = "dynamodb"
}

resource "aws_appautoscaling_policy" "reads" {
  name               = "read-target-50"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.reads.resource_id
  scalable_dimension = aws_appautoscaling_target.reads.scalable_dimension
  service_namespace  = aws_appautoscaling_target.reads.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "DynamoDBReadCapacityUtilization"
    }
    target_value = 50.0
  }
}

resource "aws_dynamodb_table" "hot" {
  name           = "hot-table"
  hash_key       = "id"
  read_capacity  = 5
  write_capacity = 5

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_backup_vault_lock_configuration" "immutable" {
  backup_vault_name   = aws_backup_vault.db.name
  changeable_for_days = 3
  min_retention_days  = 7
  max_retention_days  = 365
}

resource "aws_backup_vault" "db" {
  name = "immutable-backup-vault"
}

resource "aws_fsx_windows_file_server" "share" {
  storage_capacity      = 300
  subnet_ids            = var.subnet_ids
  throughput_capacity   = 32
  security_group_ids    = [var.fsx_sg_id]

  authentication {
    username = "admin"
    password = var.admin_password
  }

  tags = {
    Name = "acme-fsx"
  }
}

variable "subnet_ids" {
  type = list(string)
}

variable "fsx_sg_id" {
  type = string
}

variable "admin_password" {
  type      = string
  sensitive = true
}
